package com.coraline.postgame;

import java.nio.file.*;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.storage.LevelResource;

/** Small per-owner books outside ordinary scene replay. World-location
 * completion evidence stays in the existing regional discovery shards. */
final class PostgameQuestState extends SavedData {
    final UUID generation,owner;final CompoundTag raw;private String problem="";
    private PostgameQuestState(UUID generation,UUID owner){this.generation=generation;this.owner=owner;raw=new CompoundTag();raw.putInt("Version",1);raw.putUUID("Generation",generation);raw.putUUID("Owner",owner);raw.put("Candidates",new ListTag());raw.put("Recent",new ListTag());raw.putInt("Research",0);}
    private PostgameQuestState(UUID generation,UUID owner,CompoundTag n){this.generation=generation;this.owner=owner;raw=n.copy();try{if(!n.contains("Version",Tag.TAG_INT)||n.getInt("Version")!=1||!n.hasUUID("Generation")||!generation.equals(n.getUUID("Generation"))||!n.hasUUID("Owner")||!owner.equals(n.getUUID("Owner"))||!n.contains("Research",Tag.TAG_INT)||n.getInt("Research")<0||n.getInt("Research")>8||!n.contains("Candidates",Tag.TAG_LIST)||!n.contains("Recent",Tag.TAG_LIST))throw new IllegalArgumentException("Unknown quest book");var candidates=n.getList("Candidates",Tag.TAG_COMPOUND);var recent=n.getList("Recent",Tag.TAG_STRING);if(candidates.size()!=((ListTag)n.get("Candidates")).size()||candidates.size()>16||recent.size()!=((ListTag)n.get("Recent")).size()||recent.size()>6)throw new IllegalArgumentException("Unbounded quest book");var history=n.getList("ResearchHistory",Tag.TAG_COMPOUND);if(n.contains("ResearchHistory")&&!n.contains("ResearchHistory",Tag.TAG_LIST)||history.size()!=n.getInt("Research")||n.contains("ResearchHistory")&&history.size()!=((ListTag)n.get("ResearchHistory")).size())throw new IllegalArgumentException("Research progress lacks its physical receipts");String[] expected={"SEAM","DRILL","BOUNDARY","COMPONENTS","OBSERVATORY","HEART_LOCATION","HEART","WARNING"};for(int i=0;i<history.size();i++){var receipt=history.getCompound(i);if(!receipt.getString("Kind").equals(expected[i]))throw new IllegalArgumentException("Research ordering changed");if(i==3&&!receipt.hasUUID("Payment")||i==7&&!receipt.hasUUID("Warning")||i!=3&&i!=7&&(!site(receipt)||!receipt.hasUUID("Claim")))throw new IllegalArgumentException("Research receipt is incomplete");}var seen=new HashSet<UUID>();for(var row:candidates){var site=(CompoundTag)row;if(!site(site)||!seen.add(site.getUUID("Site")))throw new IllegalArgumentException("Invalid discovered candidate");}for(String key:List.of("Coraline","Wybie"))if(n.contains(key)){if(!n.contains(key,Tag.TAG_COMPOUND)||!site(n.getCompound(key))||!n.getCompound(key).contains("Assigned",Tag.TAG_LONG)||n.getCompound(key).getLong("Assigned")<0||!n.getCompound(key).contains("Mission",Tag.TAG_STRING))throw new IllegalArgumentException("Invalid active mission");if(!rewardVersion(n.getCompound(key))||!n.getCompound(key).hasUUID("Claim")||!PostgameQuests.Mission.valueOf(n.getCompound(key).getString("Mission")).family.name().equals(n.getCompound(key).getString("Family")))throw new IllegalArgumentException("Mission does not match its native location");}if(n.contains("RecentBiomes")&&(!n.contains("RecentBiomes",Tag.TAG_LIST)||n.getList("RecentBiomes",Tag.TAG_STRING).size()>6||n.getList("RecentBiomes",Tag.TAG_STRING).size()!=((ListTag)n.get("RecentBiomes")).size()))throw new IllegalArgumentException("Invalid biome history");for(String key:List.of("HandedIn","ResearchHeart"))if(n.contains(key)&&(!n.contains(key,Tag.TAG_COMPOUND)||!site(n.getCompound(key))||!rewardVersion(n.getCompound(key))||!n.getCompound(key).hasUUID("Claim")||!n.getCompound(key).contains("Assigned",Tag.TAG_LONG)||n.getCompound(key).getLong("Assigned")<0||!n.getCompound(key).contains("Mission",Tag.TAG_STRING)))throw new IllegalArgumentException("Invalid retained objective receipt");if(n.contains("HandedIn")&&(!n.getCompound("HandedIn").hasUUID("Objective")||!java.util.Set.of("coraline","wybie").contains(n.getCompound("HandedIn").getString("Giver"))))throw new IllegalArgumentException("Invalid quest giver receipt");for(String key:List.of("Payment","Warning"))if(n.contains(key)&&!n.hasUUID(key))throw new IllegalArgumentException("Invalid research receipt");if(n.contains("Mine")&&(!n.contains("Mine",Tag.TAG_COMPOUND)||!site(n.getCompound("Mine"))))throw new IllegalArgumentException("Invalid mine discovery");if(n.contains("BreachCommentAfter")&&(!n.contains("BreachCommentAfter",Tag.TAG_LONG)||n.getLong("BreachCommentAfter")<0))throw new IllegalArgumentException("Invalid world-comment clock");}catch(IllegalArgumentException unknown){problem=unknown.getMessage();}}
    private static boolean rewardVersion(CompoundTag n){return !n.contains("RewardVersion")||n.contains("RewardVersion",Tag.TAG_INT)&&n.getInt("RewardVersion")>=0&&n.getInt("RewardVersion")<=1;}
    private static boolean site(CompoundTag n){if(!n.hasUUID("Site")||!n.contains("AnchorX",Tag.TAG_INT)||!n.contains("AnchorZ",Tag.TAG_INT)||!n.contains("Y",Tag.TAG_INT)||n.getInt("Y")< -64||n.getInt("Y")>=320||Math.abs((long)n.getInt("AnchorX"))>29999920||Math.abs((long)n.getInt("AnchorZ"))>29999920||!n.contains("Family",Tag.TAG_STRING))return false;try{InfiniteStructurePlan.Family.valueOf(n.getString("Family"));return true;}catch(IllegalArgumentException unknown){return false;}}
    private static String name(UUID generation,UUID owner){return "coraline_quests_"+generation+"_"+owner;}
    static PostgameQuestState get(MinecraftServer server,UUID generation,UUID owner){var file=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(generation,owner)+".dat");return server.overworld().getDataStorage().computeIfAbsent(n->new PostgameQuestState(generation,owner,n),()->Files.notExists(file,LinkOption.NOFOLLOW_LINKS)?new PostgameQuestState(generation,owner):new PostgameQuestState(generation,owner,new CompoundTag()),name(generation,owner));}
    boolean ready(){return problem.isEmpty();}
    boolean commit(MinecraftServer server){if(!ready())return false;try{var file=server.getWorldPath(LevelResource.ROOT).resolve("data/"+name(generation,owner)+".dat");if(Files.isSymbolicLink(file)||Files.isSymbolicLink(file.getParent()))throw new java.io.IOException("Ambiguous quest storage");setDirty();server.overworld().getDataStorage().save();var n=com.coraline.rebirth.StoryRunStore.read(file);if(!n.contains("data",Tag.TAG_COMPOUND)||!n.getCompound("data").equals(raw))throw new java.io.IOException("Quest checkpoint did not match");return true;}catch(java.io.IOException|RuntimeException failed){problem="Quest storage could not be confirmed";return false;}}
    @Override public CompoundTag save(CompoundTag n){return n.merge(raw.copy());}
}
